def transform(cells):
    # 8 transforms: identity, rot90,180,270, hflip,vflip,dh
    s={(r,c) for r,c in cells}
    H=max(r for r,_ in cells)-min(r for r,_ in cells)+1
    W=max(c for _,c in cells)-min(c for _,c in cells)+1
    out=set()
    cur=s
    for i in range(4):
        r0=min(r for r,_ in cur); c0=min(c for _,c in cur)
        yield tuple(sorted((r-r0,c-c0) for r,c in cur)), i
        # rot90: (r,c)->(c, -r) normalized
        cur={(c, -r) for r,c in cur}
    # flips of original
    hf={(r, -c) for r,c in s}; vhf={( -r, c) for r,c in s}
    dh={( -r,-c) for r,c in s}
    for f,sf in (('hf',hf),('v',vhf),('d',dh)):
        r0=min(r for r,_ in sf); c0=min(c for _,c in sf)
        yield tuple(sorted((r-r0,c-c0) for r,c in sf)), f
    yield tuple(sorted((r-r0,c-c0) for r,c in s)), 'id'

