# Clean distance test: for each comp C with shape key K, find all comps (incl rotated?) with same normalized shape;
# compute centroid Chebyshev distance from src to each OTHER comp centroid, print order by distance.
for n in range(1,9):
    gi=G[f'Demo pair {n} input']; go=G[f'Demo pair {n} output']
    cs=comps(gi); H,W=len(gi),len(gi[0])
