    chgset={(r,c) for r in range(H) for c in range(W) if gi[r][c]!=go[r][c]}
    src=[(v,c) for v,c in cs if c&chgset][0]
    tgt=Counter(go[r][c] for r,c in chgset).most_common(1)[0][0]
    def cent(cells):
        return (sum(r for r,_ in cells)/len(cells), sum(c for _,c in cells)/len(cells))
    dists=[]
